"""specs_s200041.py - Sonnet-w2 family S (generated by mkfamS.py): the registry singleton slot (offset +4 of the previous instance, written 0 by the port) is a stub recording the SEH chain; 0x41e290
returns a heap object or 0 (a null p dereferences address 0+0x1c-ish only when the guard global is zero: the spec gives p non-null in that case); BASE, 0x59a9b0 (ctor of the stack-local L,
ecx as a stack marker, fills L) and 0x4ff9d0 (reads L) hooks; the slot 0x1c stub of p's vtable reads L. Fake outer SEH records 0-2; fs:[0] compared."""
from pilot import S
from recruits_util import rnd, obj, clear_hooks, hook_rec, pystub, seh_record, seh_chain


def _lread(emu, a):
    return (emu.r32(a), emu.r32(a + 4), emu.r32(a + 8), emu.rbytes(a + 0xc, 1)[0])


def _mk(gi, gg, vt):
    def gen(c):
        clear_hooks(c)
        seh_chain(c, c.rng.choice([0, 1, 2]))
        r = c.rng
        guard = r.choice([0, 0, 1, r.getrandbits(32)])
        c.emu.w32(gg, guard)
        sr = [seh_record(c, 2) for _ in range(6)]
        # a previous instance object with slot 1 (+4) stub, or none
        if r.random() < 0.6:
            old = obj(c, 0x20, {4: pystub(c, 1, ret=r.getrandbits(32), this=True, side=sr[0])}, nslots=4)
            c.emu.w32(gi, old)
        else:
            c.emu.w32(gi, 0)
        # new object: vtable with slot 0x1c stub (only used when guard == 0); 0 only when guard != 0
        def slot_side(emu, k):
            emu.calllog.append(('L1', _lread(emu, emu.arg32(0))))
            sr[1](emu, k)
        newobj = obj(c, 0x40, {0x1c: pystub(c, 1, ret=r.getrandbits(32), this=True, stackmark=(0,), side=slot_side)}, nslots=0x10)
        p = newobj if (guard == 0 or r.random() < 0.7) else 0
        hook_rec(c, 0x41e290, 1, ret=p, pop=0, side=sr[2])
        hook_rec(c, 0x5f9700, 2, ret=r.getrandbits(32), pop=8, this=True, side=sr[3])

        def ctor_side(emu, k):
            a = emu.reg('ecx')
            emu.calllog.append(('L0', _lread(emu, a)))
            emu.w32(a, r.getrandbits(32)); emu.w32(a + 4, r.getrandbits(32)); emu.w32(a + 8, r.getrandbits(32))
            emu.wbytes(a + 0xc, bytes([r.getrandbits(8)]))
            sr[4](emu, k)

        def dtor_side(emu, k):
            emu.calllog.append(('L2', _lread(emu, emu.reg('ecx'))))
            sr[5](emu, k)
        hook_rec(c, 0x59a9b0, 1, ret=r.getrandbits(32), pop=4, this='mark', side=ctor_side)
        hook_rec(c, 0x4ff9d0, 0, ret=r.getrandbits(32), this='mark', side=dtor_side)
        return [r.getrandbits(32), r.getrandbits(32)]
    return gen


S(0x50b680, 'GUESS famS 0x50b680', 'fastcall', None, ret='eax', gen=_mk(0x7011fc, 0x7011f8, 0x69d2ec), note='batch200041')
S(0x50d8e0, 'GUESS famS 0x50d8e0', 'fastcall', None, ret='eax', gen=_mk(0x7012cc, 0x7012c8, 0x69d3b8), note='batch200041')
S(0x510f90, 'GUESS famS 0x510f90', 'fastcall', None, ret='eax', gen=_mk(0x70139c, 0x701398, 0x69dad4), note='batch200041')
S(0x511830, 'GUESS famS 0x511830', 'fastcall', None, ret='eax', gen=_mk(0x7014b4, 0x7014b0, 0x69e044), note='batch200041')
